import unittest

from tests.test_cli import run
from textkit.rot import rot


class RotTest(unittest.TestCase):
    def test_rot13_examples(self):
        self.assertEqual(rot("Hello, World!", 13), "Uryyb, Jbeyq!")

    def test_keeps_case_and_other_characters(self):
        self.assertEqual(rot("aZ 09-_.é", 1), "bA 09-_.é")

    def test_wraps_around(self):
        self.assertEqual(rot("xyz", 3), "abc")
        self.assertEqual(rot("XYZ", 3), "ABC")

    def test_negative_n(self):
        self.assertEqual(rot("abc", -1), "zab")

    def test_large_n(self):
        self.assertEqual(rot("abc", 27), "bcd")
        self.assertEqual(rot("abc", 26 * 1000), "abc")
        self.assertEqual(rot("abc", -53), "xyz")

    def test_rot13_twice_is_identity(self):
        self.assertEqual(rot(rot("Round Trip", 13), 13), "Round Trip")

    def test_non_int_raises(self):
        for bad in [1.5, "13", None, True, False]:
            with self.subTest(n=bad), self.assertRaises(ValueError):
                rot("abc", bad)


class RotCommandTest(unittest.TestCase):
    def test_default_is_rot13(self):
        self.assertEqual(run("rot", "Hello, World!"), (0, "Uryyb, Jbeyq!\n", ""))

    def test_negative_n(self):
        self.assertEqual(run("rot", "abc", "--n", "-1"), (0, "zab\n", ""))

    def test_float_n_reports_error(self):
        code, out, err = run("rot", "abc", "--n", "1.5")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertEqual(err, "error: n must be an int: '1.5'\n")


if __name__ == "__main__":
    unittest.main()

